function b64(s){const t=atob(s),a=new Uint8Array(t.length);for(let i=0;i<t.length;i++)a[i]=t.charCodeAt(i);return a;}
async function gunzipB64(s){
  const data=await new Response(new Blob([b64(s)]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  return JSON.parse(new TextDecoder().decode(data));
}
async function fetchGzipJson(url){
  const r=await fetch(url);
  if(!r.ok) throw new Error('Falha ao carregar '+url+' ('+r.status+')');
  const data=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
  metrics.decompressedBytes+=data.byteLength;
  return JSON.parse(new TextDecoder().decode(data));
}
