let vegTimer=0,vegVersion=0,vegKeys='';
async function updateVegetation(){
 const bounds=map.getBounds(),keys=[];
 if(map.getZoom()>=14.2){const west=Math.floor((bounds.getWest()-.003)*100),east=Math.floor((bounds.getEast()+.003)*100),south=Math.floor((bounds.getSouth()-.003)*100),north=Math.floor((bounds.getNorth()+.003)*100);for(let x=west;x<=east;x++)for(let y=south;y<=north;y++){const key=x+','+y;if(VEG_KEYS.has(key))keys.push(key);}}
 const signature=keys.join('|');if(signature===vegKeys)return;vegKeys=signature;const version=++vegVersion,features=[];
 try{for(let i=0;i<keys.length;i+=4){const batch=await Promise.all(keys.slice(i,i+4).map(async key=>{let list=vegCache.get(key);if(list){vegCache.delete(key);vegCache.set(key,list);return list;}list=await fetchGzipJson('data/veg/'+key+'.gz');vegCache.set(key,list);vegStats.decodedRegions++;while(vegCache.size>24)vegCache.delete(vegCache.keys().next().value);return list;}));if(version!==vegVersion)return;for(const list of batch)features.push(...list);}
  if(version!==vegVersion)return;map.getSource('vegetation').setData({type:'FeatureCollection',features});vegStats.visibleFeatures=features.length;vegStats.cachedRegions=vegCache.size;
 }catch(e){vegKeys='';console.error('Vegetação:',e);}
}
